numero = doc.numero_tarjeta or ""

# Limpiar caracteres
numero = ''.join(filter(str.isdigit, numero))

if numero:

    primer_numero = numero[0]

    if primer_numero == "4":
        doc.tipo_tarjeta = "Visa"

    elif primer_numero == "5":
        doc.tipo_tarjeta = "Mastercard"

    elif primer_numero == "3":
        doc.tipo_tarjeta = "American Express"

    elif primer_numero == "6":
        doc.tipo_tarjeta = "Discover"

    else:
        doc.tipo_tarjeta = "Unknown"

if not doc.flags.get("from_crm_sync"):

    crm_deal_name = doc.custom_quotation

    if crm_deal_name:

        deal = frappe.get_doc("CRM Deal", crm_deal_name)

        if not deal.products:
            frappe.throw(
                f"El CRM Deal {crm_deal_name} no tiene productos registrados. "
                "Agrega productos al Deal antes de crear la Orden de Venta."
            )

        orden_venta = frappe.get_doc("Orden de Venta", doc.name)
        orden_venta.set("custom_products", [])

        for row in deal.products:
            orden_venta.append("custom_products", {
                "product_code": row.product_code,
                "product_name": row.product_name,
                "qty":          row.qty,
                "rate":         row.rate,
            })

        orden_venta.flags.ignore_permissions = True
        orden_venta.flags.from_crm_sync = True
        orden_venta.save()
